    await setVisitDurationById(page, "60");
    await expect(page.getByRole("textbox", { name: "Description" })).toHaveValue("rabies shot");
    await expect(page.getByRole("spinbutton", { name: "Duration (minutes)" })).toHaveValue("60");
    await expect(page.getByRole("button", { name: "Update Visit" })).toBeEnabled();

